public class Check {
    static int slow(int x, int n, int M) { // brute-force reference
        long r = 1, b = ((x % M) + M) % M;
        for (int i = 0; i < n; i++) r = (r * b) % M;
        return (int) r;
    }
    public static void main(String[] a) throws Exception {
        var m = ModularExponentiation.class.getDeclaredMethod("powMod", int.class, int.class, int.class);
        m.setAccessible(true);
        int fail = 0;
        for (int M = 1; M <= 50; M++)
            for (int x = -20; x <= 20; x++)
                for (int n = 0; n <= 30; n++) {
                    int got = (int) m.invoke(null, x, n, M);
                    int exp = slow(x, n, M);
                    if (got != exp) { System.out.printf("MISMATCH x=%d n=%d M=%d got=%d exp=%d%n", x, n, M, got, exp); if (++fail > 5) return; }
                }
        System.out.println(fail == 0 ? "ALL MATCH brute force" : "FAILURES=" + fail);
        // edge cases
        try { m.invoke(null, 2, -1, 5); System.out.println("FAIL: neg exp not rejected"); }
        catch (Exception e) { System.out.println("OK: neg exponent rejected"); }
        try { m.invoke(null, 2, 3, 0); System.out.println("FAIL: zero modulus not rejected"); }
        catch (Exception e) { System.out.println("OK: zero modulus rejected"); }
        System.out.println("M==1 -> " + m.invoke(null, 7, 5, 1));        // expect 0
        System.out.println("n==0 -> " + m.invoke(null, 7, 0, 5));        // expect 1
        System.out.println("big -> " + m.invoke(null, 2, 1000000000, 1000000007)); // no overflow
    }
}
